CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY);
CREATE TABLE IF NOT EXISTS companies(id TEXT PRIMARY KEY,payload TEXT NOT NULL,version TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sources(id TEXT PRIMARY KEY,kind TEXT NOT NULL,title TEXT NOT NULL,published_at TEXT,sha256 TEXT UNIQUE,payload TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,mode TEXT NOT NULL,owner TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS chunks(id TEXT PRIMARY KEY,document_id TEXT NOT NULL REFERENCES sources(id),page_number INTEGER,offset_start INTEGER,offset_end INTEGER,text TEXT NOT NULL);
CREATE VIRTUAL TABLE IF NOT EXISTS chunks_fts USING fts5(id UNINDEXED,document_id UNINDEXED,text,tokenize='unicode61');
CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY,payload TEXT NOT NULL,mode TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS runs(id TEXT PRIMARY KEY,company_id TEXT REFERENCES companies(id),user_id TEXT NOT NULL,role TEXT NOT NULL,mode TEXT NOT NULL,as_of TEXT NOT NULL,status TEXT NOT NULL,payload TEXT NOT NULL,created_at TEXT NOT NULL,ended_at TEXT,idem TEXT,cache_key TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS run_idempotency ON runs(user_id,company_id,idem) WHERE idem IS NOT NULL;
CREATE INDEX IF NOT EXISTS run_company ON runs(company_id,role,created_at DESC);
CREATE TABLE IF NOT EXISTS insights(id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES runs(id),company_id TEXT NOT NULL REFERENCES companies(id),event_id TEXT NOT NULL REFERENCES events(id),payload TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS insight_run ON insights(run_id);
CREATE TABLE IF NOT EXISTS saved(user_id TEXT NOT NULL,company_id TEXT NOT NULL,insight_id TEXT NOT NULL REFERENCES insights(id),created_at TEXT NOT NULL,PRIMARY KEY(user_id,company_id,insight_id));
CREATE TABLE IF NOT EXISTS feedback(user_id TEXT NOT NULL,insight_id TEXT NOT NULL REFERENCES insights(id),payload TEXT NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(user_id,insight_id));
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,payload TEXT NOT NULL,csrf TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings(id TEXT PRIMARY KEY,payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY,owner TEXT NOT NULL,status TEXT NOT NULL,kind TEXT NOT NULL,payload TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ledger(id TEXT PRIMARY KEY,date_msk TEXT NOT NULL,run_id TEXT NOT NULL,reserved TEXT NOT NULL,charged TEXT NOT NULL,state TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS ledger_day ON ledger(date_msk);
CREATE TABLE IF NOT EXISTS dataset_imports(sha256 TEXT PRIMARY KEY,payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS payment_edges(payer TEXT NOT NULL,beneficiary TEXT NOT NULL,amount TEXT NOT NULL,payment_count INTEGER NOT NULL,import_id TEXT NOT NULL,PRIMARY KEY(payer,beneficiary,import_id));
CREATE TABLE IF NOT EXISTS profile_updates(company_id TEXT PRIMARY KEY,version INTEGER NOT NULL,payload TEXT NOT NULL,updated_by TEXT NOT NULL,updated_at TEXT NOT NULL);
INSERT OR IGNORE INTO schema_migrations VALUES(1);
